export function getUniversityUpazilaOptions(districtSlug: string): UpazilaOption[] {
  return BD_UNIVERSITY_UPAZILA_SEEDS.filter((u) => u.districtSlug === districtSlug).map((u) => ({
    en: u.en,
    bn: u.bn,
  }));
}
